\title{The Fifth-Power Congruence Modulo Five\\ and Its Pythagorean Consequences}
\author{Aristotle}
\date{2026-07-02}

\begin{document}
\maketitle

\begin{abstract}
We give a fully elementary, self-contained proof that for every integer $a$, the
quantity $a^5 - a$ is divisible by $5$ --- the case $p = 5$ of Fermat's little
theorem --- using nothing beyond the arithmetic of remainders. The argument
reduces an assertion about infinitely many integers to a finite case analysis
over the five residues modulo $5$. We then develop the surrounding structure:
the table of quadratic residues modulo $5$ (namely $\{0,1,4\}$), and we use it
to derive a classical consequence for Pythagorean triples --- every triple
$(a,b,c)$ with $a^2+b^2=c^2$ contains an entry divisible by $5$, and, together
with the analogous obstructions modulo $3$ and $4$, the product $abc$ is always
divisible by $60$ with $60$ sharp. We situate the $p=5$ identity within the
general family $a^k-a$, whose universal modulus is the product of primes $p$
with $(p-1)\mid(k-1)$, and we discuss algorithmic and cryptographic
ramifications.
\end{abstract}

\section{Introduction}

The congruence
\[
a^5 \equiv a \pmod 5, \qquad \text{equivalently} \qquad 5 \mid a^5 - a,
\]
holding for every integer $a$, is the specialization to the prime $5$ of
Fermat's little theorem. While the general theorem admits proofs via group
theory (Lagrange's theorem applied to $(\mathbb{Z}/p\mathbb{Z})^\times$) or
combinatorics (necklace counting), our aim is a maximally elementary treatment
of the single prime $p=5$, requiring only division with remainder. The
elementary route exposes the residue table of squares modulo $5$, which is the
shared engine behind a family of Pythagorean divisibility facts.

\section{Definitions and preliminaries}

Throughout, $a,b,c,n$ denote integers and $p$ a prime.

\begin{definition}[Divisibility]
For integers $m,n$, we write $m \mid n$ if there is an integer $k$ with $n=mk$.
\end{definition}

\begin{definition}[Congruence]
For a positive integer $m$, we write $a \equiv b \pmod m$ if $m \mid (a-b)$.
This is an equivalence relation compatible with addition and multiplication:
$a \equiv a'$ and $b \equiv b'$ imply $a+b \equiv a'+b'$ and $ab \equiv a'b'$.
\end{definition}

\begin{definition}[Residue]
The \emph{residue} of $a$ modulo $m$ is the unique integer $r$ with
$0 \le r < m$ and $a \equiv r \pmod m$.
\end{definition}

\begin{definition}[Quadratic residue]
A residue $r$ modulo $m$ is a \emph{quadratic residue} if $r \equiv x^2 \pmod m$
for some integer $x$; otherwise it is a \emph{quadratic non-residue}.
\end{definition}

\begin{definition}[Pythagorean triple]
A \emph{Pythagorean triple} is an ordered triple $(a,b,c)$ of positive integers
with $a^2+b^2=c^2$.
\end{definition}

\begin{lemma}[Five-way residue decomposition]\label{lem:res}
For every integer $a$ there is a unique integer $q$ and residue
$r \in \{0,1,2,3,4\}$ with $a = r + 5q$.
\end{lemma}
\begin{proof}
Division with remainder of $a$ by $5$.
\end{proof}

\section{The main congruence}

\begin{theorem}[Fermat's little theorem, $p=5$]\label{thm:main}
For every integer $a$, \; $5 \mid a^5 - a$.
\end{theorem}
\begin{proof}[Proof (residue case analysis)]
By Lemma~\ref{lem:res} write $a = r + 5q$ with $r \in \{0,1,2,3,4\}$. Since
congruence is compatible with multiplication, $a^5 - a \equiv r^5 - r \pmod 5$,
so it suffices to check the five representatives:
\[
\begin{array}{c|c|c|c}
r & r^5 & r^5 - r & \text{multiple of }5\\\hline
0 & 0    & 0    & 5\cdot 0\\
1 & 1    & 0    & 5\cdot 0\\
2 & 32   & 30   & 5\cdot 6\\
3 & 243  & 240  & 5\cdot 48\\
4 & 1024 & 1020 & 5\cdot 204
\end{array}
\]
In each row $r^5 - r$ is a multiple of $5$; hence so is $a^5 - a$.
\end{proof}

For completeness, substituting $a = r+5q$ and expanding gives explicit integer
cofactors $Q_r(q)$ with $a^5 - a = 5\,Q_r(q)$:
\begin{align*}
r=0:&\quad a^5-a = 5\,(625q^5 - q),\\
r=1:&\quad a^5-a = 5\,(625q^5 + 625q^4 + 250q^3 + 50q^2 + 4q),\\
r=2:&\quad a^5-a = 5\,(625q^5 + 1250q^4 + 1000q^3 + 400q^2 + 79q + 6),\\
r=3:&\quad a^5-a = 5\,(625q^5 + 1875q^4 + 2250q^3 + 1350q^2 + 404q + 48),\\
r=4:&\quad a^5-a = 5\,(625q^5 + 2500q^4 + 4000q^3 + 3200q^2 + 1279q + 204).
\end{align*}
Each is verified by expanding both sides as polynomials in $q$.

\begin{proof}[Alternative proof (factorization)]
Factor $a^5 - a = a(a-1)(a+1)(a^2+1)$. If $a \equiv 0,1,4 \pmod 5$ then
respectively $a$, $a-1$, $a+1$ is divisible by $5$. If $a \equiv 2$ or $3$, then
$a^2 \equiv 4$, so $a^2+1 \equiv 0 \pmod 5$. In all cases one factor is
divisible by $5$.
\end{proof}

\begin{corollary}
The divisibility $5 \mid a^5 - a$ holds for every integer in any finite range;
e.g. for all $a$ with $-1000 \le a \le 1000$, as an immediate instance of
Theorem~\ref{thm:main}.
\end{corollary}

\section{Quadratic residues modulo five}

\begin{proposition}[Square table mod $5$]\label{prop:sq}
The quadratic residues modulo $5$ are exactly $\{0,1,4\}$:
\[
0^2\equiv0,\; 1^2\equiv1,\; 2^2\equiv4,\; 3^2\equiv4,\; 4^2\equiv1 \pmod 5.
\]
The residues $2$ and $3$ are quadratic non-residues.
\end{proposition}
\begin{proof}
Direct evaluation, using that $x^2 \bmod 5$ depends only on $x \bmod 5$.
\end{proof}

\begin{proposition}[Sums of two squares mod $5$]\label{prop:sum}
If $a,b$ are both coprime to $5$, then $a^2+b^2 \bmod 5 \in \{0,2,3\}$, and of
these only $0$ is a quadratic residue modulo $5$.
\end{proposition}
\begin{proof}
By Proposition~\ref{prop:sq} each nonzero square is $1$ or $4$. The unordered
sums are $1+1=2$, $1+4\equiv0$, $4+4\equiv3$. Comparing with $\{0,1,4\}$ shows
only $0$ is a square.
\end{proof}

\section{Pythagorean consequences}

\begin{theorem}[Every Pythagorean triple contains a multiple of five]\label{thm:pyth}
For every Pythagorean triple $(a,b,c)$, at least one of $a,b,c$ is divisible by
$5$.
\end{theorem}
\begin{proof}
Suppose $5 \nmid a$ and $5 \nmid b$. By Proposition~\ref{prop:sum},
$c^2 = a^2+b^2 \equiv 0,2,$ or $3 \pmod 5$. But $c^2$ is a square, hence
$\equiv 0,1,$ or $4$ by Proposition~\ref{prop:sq}. The only common value is $0$,
forcing $c^2 \equiv 0$ and, since $5$ is prime, $5 \mid c$.
\end{proof}

\begin{theorem}[Universal divisor $60$, sharp]\label{thm:sixty}
For every Pythagorean triple $(a,b,c)$, $60 \mid abc$, and $60$ is the largest
integer dividing $abc$ for all triples.
\end{theorem}
\begin{proof}[Proof sketch]
Three independent obstructions cooperate: (1) modulo $4$, the even leg is
divisible by $4$; (2) modulo $3$, since squares are $\{0,1\}$, if neither leg
were divisible by $3$ then $a^2+b^2 \equiv 2 \pmod 3$ is not a square, so $3$
divides some entry; (3) modulo $5$, Theorem~\ref{thm:pyth}. As $3,4,5$ are
pairwise coprime, $3\cdot4\cdot5 = 60 \mid abc$. Sharpness follows from
$(3,4,5)$ with product $60$.
\end{proof}

\section{The general fixed-power congruence}

\begin{theorem}[Universal modulus of $a^k-a$]\label{thm:gen}
Fix $k \ge 2$. The largest integer $m$ with $m \mid a^k - a$ for all integers
$a$ is
\[
m = \prod_{\substack{p \text{ prime}\\ (p-1)\mid(k-1)}} p.
\]
\end{theorem}
\begin{proof}[Proof sketch]
For a prime $p$, Fermat's little theorem gives $a^{1+t(p-1)} \equiv a \pmod p$
for all $t \ge 0$; hence $(p-1)\mid(k-1)$ implies $p \mid a^k - a$ for all $a$.
Conversely, if $(p-1)\nmid(k-1)$, a primitive root $g$ modulo $p$ satisfies
$g^k \not\equiv g$, so $p$ does not divide the universal modulus. No square
$p^2$ is forced since $a=p$ yields $a^k-a = p(p^{k-1}-1)$ with
$p \nmid p^{k-1}-1$.
\end{proof}

\begin{corollary}
For $k=5$, the primes with $(p-1)\mid 4$ are $\{2,3,5\}$, so $a^5-a$ is
universally divisible by $30$, strengthening Theorem~\ref{thm:main}. For $k=3$,
the primes with $(p-1)\mid 2$ are $\{2,3\}$, recovering $6 \mid a^3-a$.
\end{corollary}

\section{Algorithms}

\textbf{Algorithm A (Residue-reduction verifier).} Compute $r = a \bmod 5$ and
check $r^5 - r \equiv 0 \pmod 5$ from a size-$5$ table; $O(1)$ per input.

\textbf{Algorithm B (Universal-modulus computation).} Enumerate primes $p \le k$,
retain those with $(p-1)\mid(k-1)$, and multiply; $O(k\log\log k)$ with a sieve.

\textbf{Algorithm C (Pythagorean five-witness).} Scan $(a,b,c)$ and return the
first entry divisible by $5$; correctness is Theorem~\ref{thm:pyth}.

\section{Applications}

The identity $a^5 \equiv a \pmod 5$ is a template for power-preserving maps in
checksums and hashing over prime fields. Its composite generalization
$m^{ed} \equiv m$ underlies RSA encryption. Theorem~\ref{thm:pyth} and
Proposition~\ref{prop:sum} provide residue sieves that prune candidate
solutions to quadratic Diophantine equations.

\section{Discussion}

The elementary proof illustrates how infinite arithmetic assertions collapse to
finite residue computations, and how a single residue table drives both the
fifth-power congruence and the Pythagorean divisibility structure culminating in
the sharp divisor $60$. Open directions include the exact universal modulus of
$a^k-a$ and its link to Carmichael numbers, the representability of residues as
sums of two squares, and fixed-point densities of $x \mapsto x^m$.

\end{document}

