from typing import List

def cofactor_pow_five(a: int) -> int:
    """Return k with a**5 - a == 5 * k."""
    value = a ** 5 - a
    assert value % 5 == 0
    return value // 5

def verify_range(lo: int, hi: int) -> bool:
    return all((a ** 5 - a) % 5 == 0 for a in range(lo, hi + 1))

if __name__ == "__main__":
    print("All a in [-10000, 10000] satisfy 5 | a^5 - a:", verify_range(-10000, 10000))
    for a in (2, 3, 7, -3, 123):
        print(f"a={a}: a^5 - a = {a**5 - a} = 5 * {cofactor_pow_five(a)}")

from typing import List, Tuple

def generate_pythagorean_triples(limit: int) -> List[Tuple[int, int, int]]:
    out: List[Tuple[int, int, int]] = []
    for a in range(1, limit + 1):
        for b in range(a + 1, limit + 1):
            c2 = a * a + b * b
            c = int(c2 ** 0.5)
            if c * c == c2 and c <= limit:
                out.append((a, b, c))
    return out

def five_witness(t: Tuple[int, int, int]) -> int:
    for x in t:
        if x % 5 == 0:
            return x
    raise ValueError("theorem violated")

if __name__ == "__main__":
    triples = generate_pythagorean_triples(100)
    print("triples:", len(triples))
    print("all contain a multiple of 5:", all(any(x % 5 == 0 for x in t) for t in triples))
    print("all products divisible by 60:", all((a*b*c) % 60 == 0 for a, b, c in triples))
    for t in triples[:8]:
        print(t, "-> 5-witness", five_witness(t))

from typing import List

def is_prime(n: int) -> bool:
    if n < 2:
        return False
    d = 2
    while d * d <= n:
        if n % d == 0:
            return False
        d += 1
    return True

def universal_modulus(k: int) -> int:
    """Product of primes p with (p-1) | (k-1): the sharp divisor of a^k - a."""
    m = 1
    for p in range(2, k + 1):
        if is_prime(p) and (k - 1) % (p - 1) == 0:
            m *= p
    return m

if __name__ == "__main__":
    for k in range(2, 15):
        m = universal_modulus(k)
        ok = all((a ** k - a) % m == 0 for a in range(-50, 51))
        print(f"k={k:2d}: modulus={m:5d} confirmed={ok}")

